use crate::{editor::{Editor,Action},commands::{Command,parse}};
fn command(e:&mut Editor,line:&str)->Result<crate::editor::Change,&'static str>{let action=if let Some(result)=e.tool_line(line){result?}else{let Command::Editor(action)=parse(line).map_err(|_|"Invalid command")?else{return Err("Editor command")};action};e.apply(action)}
#[test]
fn arctic_toggle_and_strict_options_preserve_originals_pending_points_annotations_and_redo(){
 let mut e=Editor::default();e.apply(Action::Close).unwrap();e.apply(Action::AddBox).unwrap();let id=e.scene.objects()[0].id;e.select_objects([id],false);let before=e.scene.objects()[0].geometry().unwrap().to_proto();e.apply(Action::Translate([1.,0.,0.])).unwrap();let moved=e.scene.placement(id).unwrap();e.apply(Action::Undo).unwrap();command(&mut e,"Length BoundingBox").unwrap();let mark=e.mark.clone();assert!(mark.is_some());let epoch=e.interaction_epoch;command(&mut e,"aRcTiC oN").unwrap();assert!(e.arctic);assert_eq!(e.mark,mark);assert_eq!(e.interaction_epoch,epoch);assert_eq!(e.scene.objects()[0].geometry().unwrap().to_proto(),before);command(&mut e,"Arctic Off").unwrap();assert!(!e.arctic);command(&mut e,"Arctic").unwrap();assert!(e.arctic);for line in ["Arctic No","Arctic On Off","Arctic On extra"]{assert!(command(&mut e,line).is_err());assert!(e.arctic);}command(&mut e,"Line").unwrap();command(&mut e,"w0,0,0").unwrap();let points=e.draft.as_ref().unwrap().points.clone();let epoch=e.interaction_epoch;command(&mut e,"Arctic Off").unwrap();assert_eq!(e.draft.as_ref().unwrap().points,points);assert_eq!(e.interaction_epoch,epoch);command(&mut e,"Escape").unwrap();e.apply(Action::Redo).unwrap();assert_eq!(e.scene.placement(id).unwrap().m,moved.m);assert_eq!(e.scene.objects()[0].geometry().unwrap().to_proto(),before);
}
